package alphametics

import (
	"errors"
	"fmt"
	"sort"
	"strings"
)

// colLetter is the net signed coefficient of one letter within a single
// column of the addition.
type colLetter struct {
	letter int
	coeff  int
}

// Solve solves an alphametics puzzle such as "SEND + MORE == MONEY".
//
// The puzzle consists of words on the left of "==" that are added together
// and must equal the words on the right. Each letter stands for a distinct
// digit, and the first letter of a multi-letter word may not be zero.
//
// Solve returns a map assigning a digit to every letter in the puzzle, or an
// error if the puzzle has no solution.
func Solve(puzzle string) (map[string]int, error) {
	eq := strings.Split(puzzle, "==")
	if len(eq) != 2 {
		return nil, errors.New("invalid puzzle: expected exactly one '=='")
	}
	left, err := parseWords(eq[0])
	if err != nil {
		return nil, err
	}
	right, err := parseWords(eq[1])
	if err != nil {
		return nil, err
	}

	type term struct {
		word []rune
		sign int // +1 for the left side of "==", -1 for the right side
	}
	terms := make([]term, 0, len(left)+len(right))
	for _, w := range left {
		terms = append(terms, term{word: w, sign: 1})
	}
	for _, w := range right {
		terms = append(terms, term{word: w, sign: -1})
	}

	// Index the distinct letters in order of first appearance.
	letterIdx := make(map[rune]int)
	letters := make([]rune, 0, 10)
	leading := make([]bool, 0, 10)
	for _, t := range terms {
		for i, r := range t.word {
			if _, ok := letterIdx[r]; !ok {
				letterIdx[r] = len(letters)
				letters = append(letters, r)
				leading = append(leading, false)
			}
			if i == 0 && len(t.word) > 1 {
				leading[letterIdx[r]] = true
			}
		}
	}
	n := len(letters)
	if n > 10 {
		return nil, errors.New("no solution: more than ten distinct letters")
	}

	maxLen := 0
	for _, t := range terms {
		if len(t.word) > maxLen {
			maxLen = len(t.word)
		}
	}

	// For each column (column 0 is the right-most), the net coefficient of
	// every distinct letter occurring in it.
	cols := make([][]colLetter, maxLen)
	for c := 0; c < maxLen; c++ {
		coef := make(map[int]int)
		for _, t := range terms {
			pos := len(t.word) - 1 - c
			if pos < 0 {
				continue
			}
			coef[letterIdx[t.word[pos]]] += t.sign
		}
		for l, s := range coef {
			cols[c] = append(cols[c], colLetter{letter: l, coeff: s})
		}
		sort.Slice(cols[c], func(i, j int) bool {
			return cols[c][i].letter < cols[c][j].letter
		})
	}

	assign := make([]int, n)
	for i := range assign {
		assign[i] = -1
	}
	used := make([]bool, 10)

	// search checks column col, given the carry from the column to its right.
	// A column is valid when its letters' digits plus the incoming carry form
	// a multiple of ten; the quotient is the carry into the next column.
	var search func(col, carry int) bool
	search = func(col, carry int) bool {
		if col == maxLen {
			return carry == 0
		}

		known := 0
		var unassigned []colLetter
		for _, cl := range cols[col] {
			if d := assign[cl.letter]; d >= 0 {
				known += cl.coeff * d
			} else {
				unassigned = append(unassigned, cl)
			}
		}
		base := carry + known
		if len(unassigned) == 0 {
			if base%10 == 0 {
				return search(col+1, base/10)
			}
			return false
		}

		// Solve for the letter whose coefficient shares the fewest factors
		// with 10: its digit is the most constrained by the column equation.
		solver := 0
		for i, cl := range unassigned {
			if gcd(abs(cl.coeff), 10) < gcd(abs(unassigned[solver].coeff), 10) {
				solver = i
			}
		}
		solvCoeff := unassigned[solver].coeff
		solvLetter := unassigned[solver].letter
		others := make([]colLetter, 0, len(unassigned)-1)
		others = append(others, unassigned[:solver]...)
		others = append(others, unassigned[solver+1:]...)

		// enumerate assigns the other letters of the column; the solver
		// letter's digit is then forced by the column equation modulo 10.
		var enumerate func(i, sum int) bool
		enumerate = func(i, sum int) bool {
			if i == len(others) {
				r := mod10(-(base + sum))
				for d := 0; d <= 9; d++ {
					if used[d] || (leading[solvLetter] && d == 0) {
						continue
					}
					if (solvCoeff*d-r)%10 != 0 {
						continue
					}
					assign[solvLetter] = d
					used[d] = true
					if search(col+1, (base+sum+solvCoeff*d)/10) {
						return true
					}
					used[d] = false
					assign[solvLetter] = -1
				}
				return false
			}
			l := others[i]
			for d := 0; d <= 9; d++ {
				if used[d] || (leading[l.letter] && d == 0) {
					continue
				}
				assign[l.letter] = d
				used[d] = true
				if enumerate(i+1, sum+l.coeff*d) {
					return true
				}
				used[d] = false
				assign[l.letter] = -1
			}
			return false
		}
		return enumerate(0, 0)
	}

	if !search(0, 0) {
		return nil, errors.New("no solution")
	}

	result := make(map[string]int, n)
	for i, l := range letters {
		result[string(l)] = assign[i]
	}
	return result, nil
}

// parseWords splits a side of the equation into its words.
func parseWords(s string) ([][]rune, error) {
	parts := strings.Split(s, "+")
	words := make([][]rune, 0, len(parts))
	for _, p := range parts {
		w := strings.TrimSpace(p)
		if w == "" {
			return nil, errors.New("invalid puzzle: empty term")
		}
		for _, r := range w {
			if r < 'A' || r > 'Z' {
				return nil, fmt.Errorf("invalid puzzle: unexpected character %q", r)
			}
		}
		words = append(words, []rune(w))
	}
	return words, nil
}

// mod10 returns x modulo 10 in the range [0, 10).
func mod10(x int) int {
	return (x%10 + 10) % 10
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func gcd(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

